
const perguntas = [
    {
            pergunta: "1. O que é gravidez na adolescência?",
                    alternativas: [
                                "Gravidez entre 10 e 19 anos",
                                            "Gravidez após os 30 anos",
                                                        "Gravidez somente aos 20 anos"
                                                                ],
                                                                        correta: 0
                                                                            },

                                                                                {
                                                                                        pergunta: "2. Qual é uma forma de prevenção?",
                                                                                                alternativas: [
                                                                                                            "Não buscar informações",
                                                                                                                        "Utilizar preservativos",
                                                                                                                                    "Ignorar os cuidados"
                                                                                                                                            ],
                                                                                                                                                    correta: 1
                                                                                                                                                        },

                                                                                                                                                            {
                                                                                                                                                                    pergunta: "3. Qual pode ser uma consequência?",
                                                                                                                                                                            alternativas: [
                                                                                                                                                                                        "Dificuldade para continuar os estudos",
                                                                                                                                                                                                    "Ausência de responsabilidades",
                                                                                                                                                                                                                "Nenhuma mudança na rotina"
                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                correta: 0
                                                                                                                                                                                                                                    },

                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                pergunta: "4. Quem pode oferecer orientação?",
                                                                                                                                                                                                                                                        alternativas: [
                                                                                                                                                                                                                                                                    "Somente amigos",
                                                                                                                                                                                                                                                                                "Profissionais de saúde",
                                                                                                                                                                                                                                                                                            "Pessoas desconhecidas"
                                                                                                                                                                                                                                                                                                    ],
                                                                                                                                                                                                                                                                                                            correta: 1
                                                                                                                                                                                                                                                                                                                },

                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                            pergunta: "5. Qual é a importância da informação?",
                                                                                                                                                                                                                                                                                                                                    alternativas: [
                                                                                                                                                                                                                                                                                                                                                "Não faz diferença",
                                                                                                                                                                                                                                                                                                                                                            "Ajuda na prevenção e nas escolhas conscientes",
                                                                                                                                                                                                                                                                                                                                                                        "Aumenta os riscos"
                                                                                                                                                                                                                                                                                                                                                                                ],
                                                                                                                                                                                                                                                                                                                                                                                        correta: 1
                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                                                            let numeroAtual = 0;
                                                                                                                                                                                                                                                                                                                                                                                            let pontos = 0;
                                                                                                                                                                                                                                                                                                                                                                                            let respondeu = false;

                                                                                                                                                                                                                                                                                                                                                                                            function mostrarPergunta() {

                                                                                                                                                                                                                                                                                                                                                                                                respondeu = false;

                                                                                                                                                                                                                                                                                                                                                                                                    const pergunta = perguntas[numeroAtual];

                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("pergunta").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                `<h3>${pergunta.pergunta}</h3>`;

                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("resultado").textContent = "";

                                                                                                                                                                                                                                                                                                                                                                                                                        const alternativas =
                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("alternativas");

                                                                                                                                                                                                                                                                                                                                                                                                                                    alternativas.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                        pergunta.alternativas.forEach((alternativa, indice) => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                const botao = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.textContent = alternativa;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.onclick = () => verificarResposta(indice);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alternativas.appendChild(botao);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("proximo").style.display = "none";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("pontuacao").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `Pergunta ${numeroAtual + 1} de ${perguntas.length}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function verificarResposta(indice) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (respondeu) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    respondeu = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const correta = perguntas[numeroAtual].correta;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botoes = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "#alternativas button"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (indice === correta) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pontos++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("resultado").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Parabéns! Você acertou! 💗";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("resultado").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Resposta incorreta. Vamos aprender juntos!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botoes.forEach((botao, i) => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (i === correta) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.style.background = "#a8dfb5";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (i === indice) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.style.background = "#f2a1a1";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("proximo").style.display = "inline-block";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function proximaPergunta() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            numeroAtual++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (numeroAtual < perguntas.length) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mostrarPergunta();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    finalizarQuiz();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function finalizarQuiz() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("pergunta").innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "<h2>Quiz finalizado! 🎉</h2>";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("alternativas").innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("resultado").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `Você acertou ${pontos} de ${perguntas.length} perguntas!`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("pontuacao").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Continue aprendendo e compartilhando informações!";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const botao = document.getElementById("proximo");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.textContent = "Refazer quiz";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.style.display = "inline-block";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.onclick = reiniciarQuiz;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function reiniciarQuiz() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    numeroAtual = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        pontos = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("proximo").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Próxima pergunta";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("proximo").onclick =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                proximaPergunta;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarPergunta();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function rolarPara(id) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById(id).scrollIntoView({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                behavior: "smooth"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mostrarPergunta();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    